        op=args[1] if isattr and len(args)>1 else None; target=args[2] if isattr and len(args)>2 else None
        out=[]
        for x in v:
            y=attr(x,path) if isattr else x
            ok=truth(y)
            if op:
                try: ok={'==':lambda:y==target,'!=':lambda:y!=target,'>':lambda:y>target,'>=':lambda:y>=target,'<':lambda:y<target,'<=':lambda:y<=target,'in':lambda:y in target}[op]()
                except: ok=False
            if ok != reject: out.append(x)
        return out
    return v

SAFE={'range':range,'dict':lambda **kw:kw,'cycler':None,'namespace':lambda **kw:kw,'len':len,'min':min,'max':max,'abs':abs,'str':str,'int':int,'float':float,'enumerate':enumerate,'zip':zip}

def eval_expr(expr,ctx):
    expr=expr.strip()
    # Pipeline, ignoring pipes inside quote/brackets
    pieces=[]; st=0; q=None; depth=0; i=0
    while i<len(expr):
        c=expr[i]
        if q:
            if c==q and (i==0 or expr[i-1]!='\\'): q=None
        elif c in "'\"": q=c
        elif c in '([{': depth+=1
        elif c in ')]}': depth-=1
        elif c=='|' and depth==0:
            pieces.append(expr[st:i].strip()); st=i+1
        i+=1
    pieces.append(expr[st:].strip())
    base=pieces.pop(0)
    base=re.sub(r'\b(true|false|none|True|False|None)\b',lambda m:{'true':'True','false':'False','none':'None'}.get(m.group(),m.group()),base)
    base=re.sub(r'\b(and|or|not)\b',lambda m:m.group(),base)
    base=re.sub(r'\b([a-zA-Z_]\w*)\b',lambda m: m.group() if m.group() in ('True','False','None','and','or','not','in','is') else f"_get({m.group()!r})",base)
    base=base.replace(' is not ', ' != ').replace(' is ', ' == ')
