    base=re.sub(r"_get\('([^']+)'\)((?:\.[A-Za-z_]\w*|\[[^]]+\])+)" ,lambda m:"_path("+repr(m.group(1))+","+repr(re.findall(r'\.([A-Za-z_]\w*)|\[([^]]+)\]',m.group(2)))+")",base)
    env['_path']=lambda k,parts: __import__('functools').reduce(lambda a,p:attr(a,p[0] or p[1].strip("'\"")),parts,ctx.get(k,Undefined(k)))
    try: val=eval(base,{'__builtins__':{}},env)
