                        except: pass
            val=filters(val,m.group(1),args)
    return val

TOK=re.compile(r'({{.*?}}|{%.*?%}|{#.*?#})',re.S)
def render(template, context=None, autoescape='none', strict=False, trim_blocks=False,lstrip_blocks=False, syntax=None):
    ctx=dict(context or {}); tokens=TOK.split(template)
    def emit(v):
        if isinstance(v,Safe): return str(v)
        s=fmt(v)
        if autoescape in ('html','true',True): return html.escape(s,quote=True)
        return s
    def block(i, stops=()):
        out=''
        while i<len(tokens):
            t=tokens[i]
            if t.startswith('{%'):
                tag=t[2:-2].strip(); name=tag.split(None,1)[0] if tag else ''
                if name in stops: return out,i,tag
                if name=='if':
                    yes=eval_expr(tag[2:],ctx); i+=1; chunk,i,end=block(i,('elif','else','endif'))
                    chosen=chunk if yes else ''
                    while end.startswith('elif'):
                        cond=eval_expr(end[4:],ctx); i+=1; sub,i,end=block(i,('elif','else','endif'))
                        if not chosen and cond: chosen=sub
                    if end.startswith('else'):
                        i+=1; sub,i,end=block(i,('endif',))
                        if not yes and not chosen: chosen=sub
                    i+=1; out+=chosen; continue
                if name=='for':
                    m=re.match(r'for\s+(.+?)\s+in\s+(.+)',tag,re.S); vars=m.group(1).split(','); seq=eval_expr(m.group(2),ctx); i+=1
                    body,i,end=block(i,('endfor',)); old={k:ctx.get(k,Undefined()) for k in vars}
                    for item in seq if seq is not None else []:
                        vals=item if len(vars)>1 and isinstance(item,(tuple,list)) else [item]
                        for k,v in zip(vars,vals): ctx[k.strip()]=v
                        out+=render(body,ctx,autoescape,strict,trim_blocks,lstrip_blocks,syntax)
                    for k,v in old.items():
                        if isinstance(v,Undefined):ctx.pop(k.strip(),None)
                        else:ctx[k.strip()]=v
                    i+=1; continue
                if name=='set':
                    m=re.match(r'set\s+(\w+)\s*=\s*(.*)',tag,re.S)
                    if m: ctx[m.group(1)]=eval_expr(m.group(2),ctx)
                i+=1; continue
