"""Helpers for minijinja-cli advanced expression output modes."""
import json


def expression_output(value, mode="print"):
    """Return (stdout_text, process_status) for a computed expression value."""
    if mode == "status":
        if isinstance(value, int) and not isinstance(value, bool):
            return "", value & 255
        if isinstance(value, float):
            return "", 0
        # The CLI treats non-boolean, non-numeric values as failure when falsey.
        return "", 0 if _truth(value) else 1
    if mode in ("json", "json-pretty"):
        return json.dumps(value, ensure_ascii=False, indent=2 if mode == "json-pretty" else None, separators=None if mode == "json-pretty" else (",", ":")) + "\n", 0
    return display(value) + "\n", 0


def _truth(value):
    if value is None:
        return False
    if isinstance(value, (list, dict, str, tuple)):
        return bool(value)
    return bool(value)


def display(value):
    """MiniJinja's human readable value representation for CLI expressions."""
    return _display(value, False)


def _display(value, nested):
    if value is None:
        return "undefined" if nested else ""
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        return "{" + ", ".join(_display(k, True) + ": " + _display(v, True) for k, v in value.items()) + "}"
    if isinstance(value, (list, tuple)):
        return "[" + ", ".join(_display(v, True) for v in value) + "]"
    return str(value)
