def env_bool(name, default=False):
    value = os.environ.get(name)
    return default if value is None else value.lower() in ('1','true','yes','on')


def parse_define(text):
    if ':=' in text:
        k, v = text.split(':=', 1)
        try: value = json.loads(v)
        except Exception: value = v
    elif '=' in text:
        k, value = text.split('=', 1)
    else:
        k, value = text, True
    return k, value


def parse_toml_fallback(raw):
    root = {}; current = root
    for rawline in raw.splitlines():
        line = rawline.strip()
        if not line or line.startswith('#'): continue
        if line.startswith('[') and line.endswith(']'):
            current = root
            for part in line[1:-1].split('.'):
                current = current.setdefault(part.strip(), {})
            continue
        if '=' not in line: continue
        key, text = line.split('=',1); text=text.strip()
        # Remove a trailing comment outside quoted strings.
        quote = None; cut = len(text)
        for i,ch in enumerate(text):
            if ch in ('"', "'") and (i == 0 or text[i-1] != '\\'):
                quote = None if quote == ch else (ch if quote is None else quote)
            elif ch == '#' and quote is None:
                cut=i; break
        text=text[:cut].strip()
        if text in ('true','false'): value = text == 'true'
        elif text.startswith("'") and text.endswith("'"): value=text[1:-1]
        else:
            try: value=json.loads(text)
            except Exception:
                try: value=int(text)
                except Exception:
                    try: value=float(text)
                    except Exception: value=text
        current[key.strip()] = value
    return root


def load_data(path, fmt):
