    if isinstance(v, Undefined): return 'undefined'
    if v is None: return 'none'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v, dict): return '{' + ', '.join(json.dumps(k,ensure_ascii=False)+': '+fmt(x) for k,x in v.items()) + '}'
